  it.todo("collector.exponent_vector(G[0])");
  it("collector.leading_exponent(G[1])", () => {
    expect(sympyStr(new Collector([new Perm([1, 0, 2]), new Perm([2, 0, 1])], [PermutationGroup([new Perm([1, 0, 2]), new Perm([2, 0, 1]), new Perm([1, 2, 0])]), PermutationGroup([new Perm([2, 0, 1])]), PermutationGroup([new Perm([0, 1, 2])])], [2, 3]).leadingExponent(new Perm([1, 0, 2])))).toBe('1');
  });
  it("collector.map_relation(w)", () => {
    const [x0, x1] = symbols('x0 x1');
    expect(sympyStr(new Collector([new Perm([1, 0, 2]), new Perm([2, 0, 1])], [PermutationGroup([new Perm([1, 0, 2]), new Perm([2, 0, 1]), new Perm([1, 2, 0])]), PermutationGroup([new Perm([2, 0, 1])]), PermutationGroup([new Perm([0, 1, 2])])], [2, 3]).mapRelation(new FreeGroup([x0, x1]).dtype([[x1, 1], [x0, 1]])))).toBe('x1**2');
  });
